<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import Message from 'primevue/message'
import { getAdminReport, getSalesExecutives } from '../../../api/crm'
import { useCrmStore } from '../../../stores/crm'
import type { AdminReport, SalesExecutiveOption } from '../../../types/crm'

type Period = '7' | '30' | '90' | '365'
const crm = useCrmStore()
const report = ref<AdminReport>({ kpi:{totalVisits:0,withinRadius:0,outsideRadius:0,wonProspects:0}, trends:[], stages:[], performance:[], territories:[] })
const executives = ref<SalesExecutiveOption[]>([])
const period = ref<Period>('30')
const team = ref('')
const territory = ref('')
const searchQuery = ref('')
const loading = ref(false)
const error = ref('')
const exportOpen = ref(false)
const pageReady = ref(false)
let debounceTimer: ReturnType<typeof setTimeout> | undefined
let requestSequence = 0

const dateRange = computed(() => {
  const to = new Date(); const from = new Date(to)
  from.setDate(to.getDate() - Number(period.value) + 1)
  return { dateFrom: from.toISOString().slice(0, 10), dateTo: to.toISOString().slice(0, 10) }
})
const territories = computed(() => report.value.territories)
const inside = computed(() => report.value.kpi.withinRadius)
const outside = computed(() => report.value.kpi.outsideRadius)
const won = computed(() => report.value.kpi.wonProspects)
const pipelineStages = computed(() => report.value.stages)
const maxStage = computed(() => Math.max(1, ...pipelineStages.value.map(v => v.count)))
const weekly = computed(() => report.value.trends.map(v => ({ label:v.label, inside:v.withinRadius, outside:v.outsideRadius })))
const chartMax = computed(() => Math.max(1, ...weekly.value.flatMap(v => [v.inside, v.outside])))
const allPerformance = computed(() => report.value.performance.map(v => ({ id:v.salesExecutiveId,name:v.salesExecutiveName,territory:v.territory,visits:v.visits,inside:v.withinRadius,won:v.prospectsWon,conversion:v.conversion,score:v.performance })))
const performance = computed(() => {
  const query = searchQuery.value.trim().toLocaleLowerCase()
  if (!query) return allPerformance.value
  return allPerformance.value.filter(row => `${row.name} ${row.territory}`.toLocaleLowerCase().includes(query))
})

async function load() {
  const sequence = ++requestSequence
  const startedAt = Date.now()
  loading.value = true; error.value = ''
  try {
    const result = await getAdminReport({ ...dateRange.value, salesExecutiveId: team.value, territory: territory.value })
    const remaining = Math.max(0, 420 - (Date.now() - startedAt))
    if (remaining) await new Promise(resolve => setTimeout(resolve, remaining))
    if (sequence === requestSequence) report.value = result
  } catch (e) { if (sequence === requestSequence) error.value = crm.errorMessage(e) } finally { if (sequence === requestSequence) loading.value = false }
}
function scheduleLoad() { clearTimeout(debounceTimer); loading.value = true; debounceTimer = setTimeout(load, 550) }
function rows() { return allPerformance.value.map(v => [v.name, v.visits, v.inside, v.won, `${v.conversion.toFixed(1)}%`, `${v.score}%`]) }
function download(name: string, content: string, type: string) { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([content], { type })); a.download = name; a.click(); URL.revokeObjectURL(a.href) }
const fileStamp = computed(() => `${dateRange.value.dateFrom}_${dateRange.value.dateTo}`)
const teamLabel = computed(() => executives.value.find(v => v.id === team.value)?.fullName || 'All sales executives')
function exportMeta() { return [['Yummy Food - Sales Performance Report'],[`Period: ${dateRange.value.dateFrom} to ${dateRange.value.dateTo}`],[`Team: ${teamLabel.value}`],[`Territory: ${territory.value || 'All territories'}`],[],['KPI','Value'],['Total visits',report.value.kpi.totalVisits],['Within radius',inside.value],['Outside radius',outside.value],['Won prospects',won.value],[],['Sales executive','Visits','Within radius','Prospects won','Conversion','Performance'],...rows()] }
function csvCell(value: unknown) { return `"${String(value ?? '').replaceAll('"','""')}"` }
function exportCsv() { exportOpen.value=false; download(`sales-report_${fileStamp.value}.csv`, '\uFEFF'+exportMeta().map(r => r.map(csvCell).join(',')).join('\r\n'), 'text/csv;charset=utf-8') }
function htmlEscape(value: unknown) { const el=document.createElement('div'); el.textContent=String(value ?? ''); return el.innerHTML }
function exportExcel() { exportOpen.value=false; const body=exportMeta().map((r,i)=>`<tr class="r${i}">${r.map(v=>`<td>${htmlEscape(v)}</td>`).join('')}</tr>`).join(''); const html=`<html><head><meta charset="utf-8"><style>body{font-family:Arial}table{border-collapse:collapse;width:100%}td{padding:8px;border:1px solid #dfe6ef}.r0 td{background:#e63946;color:#fff;font-size:20px;font-weight:bold}.r5 td,.r11 td{background:#fff5f5;font-weight:bold}</style></head><body><table>${body}</table></body></html>`; download(`sales-report_${fileStamp.value}.xls`,html,'application/vnd.ms-excel;charset=utf-8') }
function exportPdf() { exportOpen.value=false; const popup=window.open('','_blank','width=1000,height=760'); if(!popup){error.value='Allow pop-ups to export PDF.';return}; const body=rows().map(r=>`<tr>${r.map(v=>`<td>${htmlEscape(v)}</td>`).join('')}</tr>`).join(''); popup.document.write(`<!doctype html><html><head><title>Sales report ${fileStamp.value}</title><style>@page{size:A4 landscape;margin:14mm}body{font:12px Arial;color:#172033}h1{margin-bottom:4px;color:#e63946}.meta{color:#64748b;margin-bottom:18px}.kpis{display:flex;gap:12px;margin:18px 0}.kpis div{border:1px solid #dfe6ef;border-radius:8px;padding:12px;min-width:130px}.kpis b{display:block;font-size:22px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border:1px solid #dfe6ef;text-align:left}th{background:#fff5f5}</style></head><body><h1>Sales Performance Report</h1><div class="meta">${dateRange.value.dateFrom} to ${dateRange.value.dateTo} · ${htmlEscape(teamLabel.value)} · ${htmlEscape(territory.value||'All territories')}</div><div class="kpis"><div>Total visits<b>${report.value.kpi.totalVisits}</b></div><div>Within radius<b>${inside.value}</b></div><div>Outside radius<b>${outside.value}</b></div><div>Won prospects<b>${won.value}</b></div></div><table><thead><tr><th>Sales executive</th><th>Visits</th><th>Within radius</th><th>Prospects won</th><th>Conversion</th><th>Performance</th></tr></thead><tbody>${body||'<tr><td colspan="6">No activity in this period.</td></tr>'}</tbody></table><script>window.onload=()=>{window.print();window.onafterprint=()=>window.close()}<\/script></body></html>`); popup.document.close() }
watch([period, team, territory], scheduleLoad)
onMounted(async () => {
  requestAnimationFrame(() => { pageReady.value = true })
  try { executives.value = await getSalesExecutives() } catch { /* report still works */ }
  await load()
})
onUnmounted(() => clearTimeout(debounceTimer))
</script>

<template>
  <section class="reports-page" :class="{ 'is-ready': pageReady, 'is-loading': loading }">
    <Message v-if="error" severity="error">{{ error }}</Message>
    <header class="report-header"><div><h1>Sales Reports</h1><p>See how your team performs—from field visits and territory coverage to prospect conversion.</p></div><div class="exports"><div class="export-menu"><button class="primary" @click="exportOpen=!exportOpen"><i class="pi pi-download" /> Export report <i class="pi pi-chevron-down" /></button><div v-if="exportOpen" class="export-dropdown"><button @click="exportExcel"><i class="pi pi-file-excel" /><span><strong>Export to Excel</strong><small>KPIs and results in a formatted workbook</small></span></button><button @click="exportCsv"><i class="pi pi-file" /><span><strong>Download CSV</strong><small>Raw data for further analysis</small></span></button><button @click="exportPdf"><i class="pi pi-file-pdf" /><span><strong>Save as PDF</strong><small>Print-ready landscape report</small></span></button></div></div></div></header>
    <div class="filters">
      <label><span>Periode laporan</span><select v-model="period"><option value="7">7 hari terakhir</option><option value="30">30 hari terakhir</option><option value="90">90 hari terakhir</option><option value="365">12 bulan terakhir</option></select></label>
      <label><span>Sales executive</span><select v-model="team"><option value="">Semua sales</option><option v-for="u in executives" :key="u.id" :value="u.id">{{ u.fullName }}</option></select></label>
      <label><span>Wilayah</span><select v-model="territory"><option value="">Semua wilayah</option><option v-for="v in territories" :key="v">{{ v }}</option></select></label>
      <div class="filter-summary"><i class="pi pi-calendar" /><span>{{ dateRange.dateFrom }} <b>to</b> {{ dateRange.dateTo }}</span></div>
      <button class="primary apply" :disabled="loading" @click="load"><i :class="loading ? 'pi pi-spin pi-spinner' : 'pi pi-refresh'" />{{ loading ? 'Refreshing…' : 'Refresh report' }}</button>
    </div>
    <div class="update-status" :class="{visible:loading}"><i class="pi pi-spin pi-spinner" /> Refreshing the report with your selected filters…</div>
    <div class="kpis"><article><span>Total field visits</span><strong>{{ report.kpi.totalVisits.toLocaleString() }}</strong><small>Completed during this period</small></article><article><span>Visits within radius</span><strong>{{ inside.toLocaleString() }}</strong><small>{{ report.kpi.totalVisits ? Math.round(inside / report.kpi.totalVisits * 100) : 0 }}% met the location requirement</small></article><article><span>Visits outside radius</span><strong>{{ outside.toLocaleString() }}</strong><small>{{ report.kpi.totalVisits ? Math.round(outside / report.kpi.totalVisits * 100) : 0 }}% need location review</small></article><article><span>Prospects won</span><strong>{{ won.toLocaleString() }}</strong><small>Converted during this period</small></article></div>
    <div class="charts"><article class="panel trend"><header><div><h2>Visit trends</h2><p>Completed field visits by week</p></div><div class="legend"><span><i />Within radius</span><span><i class="orange" />Outside</span></div></header><div class="bars"><div v-for="w in weekly" :key="w.label"><span class="bar inside" :style="{height:`${Math.max(3,w.inside/chartMax*100)}%`}" :title="`${w.inside} within radius`" /><span class="bar outside" :style="{height:`${Math.max(3,w.outside/chartMax*100)}%`}" :title="`${w.outside} outside radius`" /><small>{{ w.label }}</small></div></div></article>
      <article class="panel funnel"><header><div><h2>Prospect conversion</h2><p>Saved prospects moving through the funnel</p></div></header><div v-for="s in pipelineStages" :key="s.label" class="stage"><div><span>{{ s.label }}</span><strong>{{ s.count.toLocaleString() }}</strong></div><i><b :style="{width:`${s.count/maxStage*100}%`}" /></i></div></article></div>
    <article class="panel performance"><header><div><h2>Team performance</h2><p>Compare field activity, conversion, and overall results for each sales executive.</p></div><div class="performance-actions"><label class="search-box"><i class="pi pi-search" /><input v-model="searchQuery" type="search" placeholder="Search by name or territory…" aria-label="Search sales performance" /><button v-if="searchQuery" type="button" aria-label="Clear search" @click="searchQuery = ''"><i class="pi pi-times" /></button></label><RouterLink to="/admin/visit-monitoring">View visit details</RouterLink></div></header><div class="result-summary"><span>{{ performance.length }} of {{ allPerformance.length }} sales executives</span><span v-if="searchQuery">Results for “{{ searchQuery }}”</span></div><div class="table-wrap"><table><thead><tr><th>Sales executive</th><th>Total visits</th><th>Within radius</th><th>Prospects won</th><th>Conversion rate</th><th>Performance score</th></tr></thead><tbody><tr v-if="!performance.length"><td colspan="6" class="empty-state"><i class="pi pi-search" /><strong>{{ searchQuery ? 'No matching sales executives' : 'No activity for this period' }}</strong><small>{{ searchQuery ? 'Try another name or territory.' : 'Adjust the filters or select a different reporting period.' }}</small></td></tr><tr v-for="r in performance" :key="r.id"><td><strong>{{ r.name }}</strong><small>{{ r.territory || 'Territory not assigned' }}</small></td><td>{{ r.visits }}</td><td>{{ r.inside }}</td><td>{{ r.won }}</td><td>{{ r.conversion.toFixed(1) }}%</td><td><div class="meter"><i><b :style="{width:`${r.score}%`}" /></i><strong>{{ r.score }}%</strong></div></td></tr></tbody></table></div></article>
  </section>
</template>

<style scoped>
